return [
  {
    json: {
      jwt: token,
      alias,
      app_id: config.app_id,
      country: 'ES',
      aspsp_name: config.institution_id || alias,
      psu_type: 'personal',
      days: 180,
      state: $execution.id + '-' + alias,
      redirect_url: 'https://automation-n8n.homelab.alvsanand.com/webhook/enablebanking-consent',
    },
  },
