// plus the success page the browser lands on (styled like the n8n form pages).
// The sessions response comes from $('Post /sessions') - this node's immediate
// predecessor is the token-secret GET, so $json is NOT the session body.
const jwt = require('jsonwebtoken');

const session = $('Post /sessions').first().json;
const validUntil = (session.access || {}).valid_until;
if (!validUntil) {
  throw new Error(`session response carried no access.valid_until: ${JSON.stringify(session).slice(0, 200)}`);
}

const tokenGet = $('Get Token Secret - Webhook').first().json;
let tokens = {};
let tokenSecretExisted = false;
if (tokenGet.statusCode === 404) {
  tokenSecretExisted = false;
} else if (tokenGet.statusCode === 200) {
  const raw = (tokenGet.body.data || {})['tokens.json'];
  tokens = raw ? JSON.parse(atob(raw)) : {};
  tokenSecretExisted = true;
} else {
  throw new Error(`finance-enablebanking-token GET returned HTTP ${tokenGet.statusCode}`);
}

const stable = $('Get Stable Secret - Webhook').first().json;
const accounts = JSON.parse(atob(stable.data['accounts.json']));
const firstAlias = Object.keys(accounts)[0];
if (!firstAlias) {
  throw new Error('finance-enablebanking accounts.json is empty');
}
// Sessions the new consent replaces, captured before the overwrite. One
// application per fleet, so its app_id signs the DELETE calls.
const priorSessions = [...new Set(Object.values(tokens).map((t) => t && t.session_id).filter(Boolean))];
const deleteJwt = jwt.sign(
  { iss: 'enablebanking.com', aud: 'api.enablebanking.com' },
  atob(stable.data['private_key']),
  { algorithm: 'RS256', keyid: accounts[firstAlias].app_id, expiresIn: 3600 }
);

const renewals = [];
for (const resource of session.accounts || []) {
  if (!resource.uid) continue;
  const iban = (resource.account_id || {}).iban;
  const hash = resource.identification_hash;
  // Prefer the bank's stable identification hash (the FAQ's cross-session
  // matcher); fall back to IBAN for secrets written before it was captured.
  const matched = Object.entries(accounts).filter(([, cfg]) =>
    (cfg.identification_hash && hash && cfg.identification_hash === hash) ||
    (cfg.iban && iban && cfg.iban === iban)
  );
  const alias = matched.length ? matched[0][0] : null;
  if (!alias) {
    throw new Error(
      `session account ****${String(iban).slice(-4)} is not in finance-enablebanking accounts.json; add its alias first`
    );
  }
  tokens[alias] = {
    uid: resource.uid,
    valid_until: validUntil,
    session_id: session.session_id,
    identification_hash: hash,
    currency: resource.currency,
    owner_name: resource.name,
  };
  renewals.push(alias);
}
if (renewals.length === 0) {
  throw new Error('Enable Banking session authorized zero accounts; nothing to store');
}

// Delete only sessions no alias still references, so a session shared with an
// account this renewal did not touch is left alone. The new session is kept.
const referenced = new Set(Object.values(tokens).map((t) => t && t.session_id).filter(Boolean));
const superseded = priorSessions
  .filter((id) => !referenced.has(id))
  .map((id) => ({ session_id: id, jwt: deleteJwt }));

const untilDate = new Date(validUntil).toISOString().slice(0, 10);
const slackText =
  `Enable Banking token renewed for ${renewals.join(', ')}: consent valid until ${untilDate}. ` +
  'The daily pipeline picks it up on the next run.';

const escapeHtml = (text) =>
  String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = renewals
  .map((alias) => `<li><code>${escapeHtml(alias)}</code> — ${escapeHtml(accounts[alias].institution_id || 'bank')}</li>`)
  .join('');
const resultHtml = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Renew Enable Banking consent</title>
<style>
  body { margin: 0; background: #f7f7f8; color: #2d2e33;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    display: flex; justify-content: center; padding: 48px 16px; }
  .card { background: #fff; border-radius: 8px; box-shadow: 0 1px 3px rgba(0,0,0,.08);
    padding: 32px; max-width: 520px; width: 100%; }
  h1 { font-size: 22px; font-weight: 600; text-align: center; margin: 0 0 20px; }
  p { font-size: 14px; line-height: 1.5; margin: 0 0 12px; }
  ul { font-size: 14px; line-height: 1.6; margin: 0 0 16px 20px; padding: 0; }
  .ok { padding: 12px 14px; border-radius: 6px; background: #eef8f1; border: 1px solid #cfe8d8;
    font-size: 14px; line-height: 1.5; }
  footer { text-align: center; font-size: 12px; color: #7a7a7f; margin-top: 24px; }
</style></head>
<body><div class="card">
  <h1>Renew Enable Banking consent</h1>
  <p>Step 3 of 3 — done. The bank consent was renewed and stored:</p>
  <ul>${rows}</ul>
  <div class="ok">Valid until <strong>${untilDate}</strong>. The daily pipeline picks it up on the next run.</div>
  <footer>Form automated with n8n</footer>
</div></body></html>`;

const secretBody = {
  apiVersion: 'v1',
  kind: 'Secret',
  metadata: { name: 'finance-enablebanking-token', namespace: 'data' },
  data: { 'tokens.json': btoa(JSON.stringify(tokens)) },
};
return [
  {
    json: {
      token_secret_missing: !tokenSecretExisted,
      secret_body: JSON.stringify(secretBody),
      slack_text: slackText,
      result_html: resultHtml,
      has_superseded: superseded.length > 0,
      superseded,
    },
  },
];

// Build the failure page for the consent-exchange branch. Reached from the
// error output of any node in the chain (onError: continueErrorOutput), so the
// run stays loud (this branch also posts to Slack) instead of failing silently.
const item = $json;
const error = item.error || {};
const raw = error.message || error.description || JSON.stringify(item);
const message = typeof raw === 'string' ? raw : JSON.stringify(raw);
const slash = String(message).replace(/\s+/g, ' ').slice(0, 400);

const escapeHtml = (text) =>
  String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const slackText = `Enable Banking consent renewal FAILED: ${slash}. Nothing was stored - re-run the renewal form.`;
const resultHtml = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Renew Enable Banking consent</title>
<style>
  body { margin: 0; background: #f7f7f8; color: #2d2e33;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    display: flex; justify-content: center; padding: 48px 16px; }
  .card { background: #fff; border-radius: 8px; box-shadow: 0 1px 3px rgba(0,0,0,.08);
    padding: 32px; max-width: 520px; width: 100%; }
  h1 { font-size: 22px; font-weight: 600; text-align: center; margin: 0 0 20px; }
  p { font-size: 14px; line-height: 1.5; margin: 0 0 12px; }
  .bad { padding: 12px 14px; border-radius: 6px; background: #fdeef1; border: 1px solid #f3c6d0;
    font-size: 13px; line-height: 1.5; word-break: break-word; }
  footer { text-align: center; font-size: 12px; color: #7a7a7f; margin-top: 24px; }
</style></head>
<body><div class="card">
  <h1>Renew Enable Banking consent</h1>
  <p>Step 3 of 3 — <strong>not stored</strong>. Nothing changed, so it is safe to retry:</p>
  <div class="bad">${escapeHtml(slash)}</div>
  <footer>Form automated with n8n</footer>
</div></body></html>`;

return [{ json: { slack_text: slackText, result_html: resultHtml } }];

// Mint a read-only JWT per stored session for the daily GET /sessions/{id}
// liveness probe, signing each with the app_id that owns that session. That call
// reads Enable Banking's own session state and never reaches the ASPSP, so it
// spends none of the PSD2 per-endpoint data-call budget. Emits one item per
// session so "Get Session Status" probes them all.
const jwt = require('jsonwebtoken');

const stable = $('Get Stable Secret').first().json;
const pem = atob(stable.data['private_key']);
const sessions = $('Check Consent Expiry').first().json.sessions || [];
if (sessions.length === 0) {
  throw new Error('Mint Session JWT reached with no sessions to probe');
}
return sessions.map((session) => ({
  json: {
    alias: session.alias,
    session_id: session.session_id,
    jwt: jwt.sign(
      { iss: 'enablebanking.com', aud: 'api.enablebanking.com' },
      pem,
      { algorithm: 'RS256', keyid: session.app_id, expiresIn: 3600 }
    ),
  },
}));

// Combine the stored-expiry signal with the free GET /sessions/{id} probes.
// "Mint Session JWT" emits one item per session and "Get Session Status" answers
// each in order, so the two lists pair by index. On the branch with no stored
// session id, "Mint Session JWT" never ran, so it is referenced only inside the
// has_sessions guard.
const expiry = $('Check Consent Expiry').first().json;
const lines = [...(expiry.expiry_due || [])];

if (expiry.has_sessions) {
  const probes = $('Mint Session JWT').all();
  $input.all().forEach((item, index) => {
    const resp = item.json;
    if (!resp || resp.statusCode === undefined) return;
    const meta = probes[index] ? probes[index].json : {};
    const status = (resp.body || {}).status;
    if (!(resp.statusCode === 200 && status === 'AUTHORIZED')) {
      lines.push(
        `- session \`${meta.session_id}\` (${meta.alias}): ${status || `HTTP ${resp.statusCode}`}, not AUTHORIZED - ` +
          'the bank consent is no longer usable; re-link'
      );
    }
  });
}

const needsRenewal = lines.length > 0;
return [
  {
    json: {
      needs_renewal: needsRenewal,
      nudge_text: needsRenewal
        ? `Enable Banking consent needs attention:\n${lines.join('\n')}\n\nRenew now (the bank login is the one manual step): https://automation-n8n.homelab.alvsanand.com/form/7c1f51ab-5f61-4b21-9b31-01befd1d0d02`
        : 'all consents healthy',
    },
  },
];

// The mandated first flow step: resolve the ASPSP through GET /aspsps, cap the
// requested validity at its maximum_consent_validity, assert the PSU type is
// supported, and build the POST /auth body. A stored name the bank no longer
// returns stops here, naming it, instead of failing at the bank (a rebrand).
const base = $('Build Consent Request').first().json;
const aspsps = $json.aspsps || [];
const bank = aspsps.find((a) => a.name === base.aspsp_name && a.country === base.country);
if (!bank) {
  const known = aspsps.map((a) => a.name).slice(0, 20).join(', ');
  throw new Error(
    `ASPSP '${base.aspsp_name}' (${base.country}) is not in GET /aspsps; ` +
      `update institution_id in finance-enablebanking (known: ${known})`
  );
}
const maxDays = bank.maximum_consent_validity
  ? Math.floor(bank.maximum_consent_validity / 86400)
  : base.days;
const days = Math.min(base.days, maxDays);
if (Array.isArray(bank.psu_types) && bank.psu_types.length && !bank.psu_types.includes(base.psu_type)) {
  throw new Error(
    `ASPSP '${bank.name}' does not support psu_type '${base.psu_type}' (supports ${bank.psu_types.join(', ')})`
  );
}
return [
  {
    json: {
      jwt: base.jwt,
      beta: bank.beta === true,
      validity_days: days,
      auth_body: JSON.stringify({
        access: { valid_until: new Date(Date.now() + days * 86400000).toISOString() },
        aspsp: { name: bank.name, country: bank.country },
        state: base.state,
        redirect_url: base.redirect_url,
        psu_type: base.psu_type,
      }),
    },
  },
];

// Fan out one item per superseded session so "Delete Session" runs once each.
// Reached only when has_superseded is true.
return ($('Build Token Upsert').first().json.superseded || []).map((s) => ({ json: s }));
